def solve(payload):
    coefficients = payload["coefficients"]
    lo, hi, tolerance = payload["lo"], payload["hi"], payload["tolerance"]
    if lo > hi:
        return {"error": "invalid_bounds"}
    if tolerance <= 0:
        return {"error": "invalid_tolerance"}
    def evaluate(x):
        result = 0.0
        for coefficient in coefficients:
            result = result * x + coefficient
        return result
    flo, fhi = evaluate(lo), evaluate(hi)
    if flo == 0:
        return {"root": lo}
    if fhi == 0:
        return {"root": hi}
    if (flo > 0) == (fhi > 0):
        return {"error": "not_bracketed"}
    for _ in range(200):
        middle = lo + (hi - lo) / 2
        if hi - lo <= 2 * tolerance:
            return {"root": middle}
        fm = evaluate(middle)
        if fm == 0:
            return {"root": middle}
        if (fm > 0) == (flo > 0):
            lo, flo = middle, fm
        else:
            hi = middle
    return {"error": "not_converged"}

